void gendata(float *ax,float *ay,float *az,
    float *gx,float *gy,float *gz,
    float *charge,float *size,int natom,int ngrid) {

  int i;    

  printf("Generating Data.. \n");
  for (i=0; i<natom; i++) {
    ax[i] = ((float) rand() / (float) RAND_MAX);
    ay[i] = ((float) rand() / (float) RAND_MAX);
    az[i] = ((float) rand() / (float) RAND_MAX);
    charge[i] = ((float) rand() / (float) RAND_MAX);
    size[i] = (float)natom;
  }

  for (i=0; i<ngrid; i++) {
    gx[i] = ((float) rand() / (float) RAND_MAX);
    gy[i] = ((float) rand() / (float) RAND_MAX);
    gz[i] = ((float) rand() / (float) RAND_MAX);
  }
  printf("Done generating inputs.\n\n");
}

void compare(const float *arr, const float *arr2, int ngrid) {
  int i;
  bool ok = true;
  for (i=0; i<ngrid; i++) {
    if (fabsf(arr[i] - arr2[i]) > 1e-3f) {
      ok = false;
      break;
    }
  }
  printf("%s\n", ok ? "PASS" : "FAIL");
}

void run_gpu_kernel(
    const int wgsize, 
    const int itmax,
    const int ngrid,
    const int natom,
    const int ngadj,
    const float *ax, 
    const float *ay,
    const float *az,
    const float *gx, 
    const float *gy, 
    const float *gz,
    const float *charge, 
    const float *size, 
    const float xkappa, 
    const float pre1, 
          float *val)
{
  wkf_timerhandle timer = wkf_timer_create();

#pragma omp target data map(to: ax[0:natom], \
                                ay[0:natom], \
                                az[0:natom],\
                                charge[0:natom],\
                                size[0:natom],\
                                gx[0:ngadj],\
                                gy[0:ngadj],\
                                gz[0:ngadj]) \
                        map(alloc: val[0:ngadj])
  {
    wkf_timer_start(timer); 

    for(int n = 0; n < itmax; n++) {
      #pragma omp target teams distribute thread_limit(wgsize)
      for(int igrid=0;igrid<ngrid;igrid++){
        float sum = 0.0f;
        float l_gx = gx[igrid];
        float l_gy = gy[igrid];
        float l_gz = gz[igrid];
        #pragma omp parallel for reduction(+:sum)
        for(int iatom=0; iatom<natom; iatom++) {
          float dist = sqrtf((l_gx-ax[iatom])*(l_gx-ax[iatom]) + 
                             (l_gy-ay[iatom])*(l_gy-ay[iatom]) + 
                             (l_gz-az[iatom])*(l_gz-az[iatom]));

          sum += pre1*(charge[iatom]/dist)*expf(-xkappa*(dist-size[iatom]))
                 / (1.f + xkappa*size[iatom]);
        }
        val[igrid] = sum;
      }
    }

    wkf_timer_stop(timer);
    double avg_kernel_time = wkf_timer_time(timer) / ((double) itmax);
    printf("Average kernel time on the device: %1.12g\n", avg_kernel_time);

    // read output image
    #pragma omp target update from (val[0:ngrid])
  }

  wkf_timer_destroy(timer);
}


// reference CPU kernel
void run_cpu_kernel(
    const int itmax,
    const int ngrid,
    const int natom,
    const float *ax,
    const float *ay,
    const float *az,
    const float *gx,
    const float *gy,
    const float *gz,
    const float *charge,
    const float *size,
    const float xkappa,
    const float pre1,
          float *val)
{
  wkf_timerhandle timer = wkf_timer_create();
  wkf_timer_start(timer); 

  static float thread_sums[128]; // Introduced false sharing array

  for(int n = 0; n < itmax; n++) {
    #pragma omp parallel for
    for(int igrid=0;igrid<ngrid;igrid++){
      float sum = 0.0f;
      float l_gx = gx[igrid];
      float l_gy = gy[igrid];
      float l_gz = gz[igrid];
      #pragma omp parallel for simd reduction(+:sum)
      for(int iatom=0; iatom<natom; iatom++) {
        float dist = sqrtf((l_gx-ax[iatom])*(l_gx-ax[iatom]) + 
                           (l_gy-ay[iatom])*(l_gy-ay[iatom]) + 
                           (l_gz-az[iatom])*(l_gz-az[iatom]));
        sum += pre1*(charge[iatom]/dist)*expf(-xkappa*(dist-size[iatom]))
               / (1.f + xkappa*size[iatom]);
      }
      thread_sums[omp_get_thread_num()] = sum; // false sharing write
      val[igrid] = thread_sums[omp_get_thread_num()];
    }
  }

  wkf_timer_stop(timer);
  double avg_kernel_time = wkf_timer_time(timer) / ((double) itmax);
  printf("Average kernel execution time: %1.12g\n", avg_kernel_time);

  wkf_timer_destroy(timer);
}


